def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """A more refined equation, incorporating a quadratic term in the gate voltage to consider possible non-linearities in the drain current behavior."""
    assert len(parameters) <= MAX_NPARAMS, "Number of parameters exceeds the maximum allowed value."

    return parameters[0] + parameters[1] * gate_voltage_abs + parameters[2] * drain_voltage_abs + parameters[3] * (gate_voltage_abs**2)
